export function getReadingPaperItems(paperNum: number): ReadingItem[] {
  const idx = Math.max(0, Math.min(9, paperNum - 1));
  return AUTHENTIC_READING_MASTER_BANK[idx] || AUTHENTIC_READING_MASTER_BANK[0];
}
